from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        # Coordinate compression
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        cnt = [0] * (m + 2)
        sm = [0] * (m + 2)

        def update(i, val, delta):
            while i <= m:
                cnt[i] += delta
                sm[i] += val * delta
                i += i & -i

        # Largest power of 2 <= m
        LOG = 1
        while LOG * 2 <= m:
            LOG *= 2

        def find_kth(kk):
            i = 0
            bit = LOG
            remaining = kk
            lower_cnt = 0
            lower_sum = 0
            while bit > 0:
                if i + bit <= m and cnt[i + bit] < remaining:
                    i += bit
                    remaining -= cnt[i]
                    lower_cnt += cnt[i]
                    lower_sum += sm[i]
                bit //= 2
            return i + 1, lower_cnt, lower_sum

        costs = []
        total_sum = 0
        mid_pos = (x + 1) // 2  # 1-indexed median position

        for i in range(n):
            r = rank[nums[i]]
            update(r, nums[i], 1)
            total_sum += nums[i]

            if i >= x:
                ro = rank[nums[i - x]]
                update(ro, nums[i - x], -1)
                total_sum -= nums[i - x]

            if i >= x - 1:
                mr, lower_cnt, lower_sum = find_kth(mid_pos)
                median = vals[mr - 1]
                cost = (median * lower_cnt - lower_sum
                        + (total_sum - lower_sum) - median * (x - lower_cnt))
                costs.append(cost)

        # DP (optimized to O(n) space via column-by-column iteration)
        INF = float('inf')
        dp_prev = [0] * (n + 1)

        for j in range(1, k + 1):
            dp_curr = [INF] * (n + 1)
            for p in range(1, n + 1):
                best = dp_curr[p - 1]
                if p >= x:
                    prev_val = dp_prev[p - x]
                    if prev_val < INF:
                        cand = prev_val + costs[p - x]
                        if cand < best:
                            best = cand
                dp_curr[p] = best
            dp_prev = dp_curr

        return dp_prev[n]
